//! UX compliance tests - verify adherence to design system guidelines
//!
//! These tests validate that the UI follows UX best practices from
//! the design system generated by ui-ux-pro-max skill.

use nodoka::ui::*;

fn assert_approx_eq_f32(actual: f32, expected: f32, tol: f32, context: &str) {
    assert!(
        (actual - expected).abs() <= tol,
        "{context}: expected {expected}, got {actual}"
    );
}

fn srgb_to_linear(channel: f64) -> f64 {
    if channel <= 0.04045 {
        channel / 12.92
    } else {
        ((channel + 0.055) / 1.055).powf(2.4)
    }
}

fn wcag_relative_luminance(color: iced::Color) -> f64 {
    let r = srgb_to_linear(f64::from(color.r));
    let g = srgb_to_linear(f64::from(color.g));
    let b = srgb_to_linear(f64::from(color.b));
    (0.2126_f64).mul_add(r, (0.7152_f64).mul_add(g, 0.0722_f64 * b))
}

fn wcag_contrast_ratio(foreground: iced::Color, background: iced::Color) -> f64 {
    let fg = wcag_relative_luminance(foreground);
    let bg = wcag_relative_luminance(background);
    let (lighter, darker) = if fg >= bg { (fg, bg) } else { (bg, fg) };
    (lighter + 0.05) / (darker + 0.05)
}

#[test]
fn test_spacing_follows_4px_grid() {
    // Verify all spacing constants are multiples of 4
    fn multiple_of_4(value: f32) -> bool {
        let scaled = value / 4.0;
        (scaled - scaled.round()).abs() < 1e-6
    }

    assert!(
        multiple_of_4(spacing::XS),
        "XS spacing should be multiple of 4"
    );
    assert!(
        multiple_of_4(spacing::SM),
        "SM spacing should be multiple of 4"
    );
    assert!(
        multiple_of_4(spacing::MD),
        "MD spacing should be multiple of 4"
    );
    assert!(
        multiple_of_4(spacing::LG),
        "LG spacing should be multiple of 4"
    );
    assert!(
        multiple_of_4(spacing::XL),
        "XL spacing should be multiple of 4"
    );
    assert!(
        multiple_of_4(spacing::XXL),
        "XXL spacing should be multiple of 4"
    );
}

#[test]
fn test_typography_scale_monotonic() {
    fn ordered(a: f32, b: f32) -> bool {
        a < b
    }

    assert!(ordered(typography::SIZE_XS, typography::SIZE_SM));
    assert!(ordered(typography::SIZE_SM, typography::SIZE_BASE));
    assert!(ordered(typography::SIZE_BASE, typography::SIZE_LG));
    assert!(ordered(typography::SIZE_LG, typography::SIZE_XL));
    assert!(ordered(typography::SIZE_XL, typography::SIZE_XXL));
    assert!(ordered(typography::SIZE_XXL, typography::SIZE_HEADING));
}

#[test]
fn test_transition_durations_within_ux_guidelines() {
    fn within(value: u64, min: u64, max: u64) -> bool {
        (min..=max).contains(&value)
    }

    assert!(within(transitions::FAST, 150, 300));
    assert!(within(transitions::NORMAL, 150, 300));
    assert!(within(transitions::SLOW, 150, 300));
}

